/**
 * Normaliza o termo médico para busca de ícone (remove acentos e pontuações)
 */
const normalizeText = (text: string): string => {
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
};

